create table public.work_stop_reports(id uuid primary key default gen_random_uuid(),reporter_id uuid not null references public.profiles(id),hazard_type text not null,description text,zone text,is_anonymous boolean not null default false,photo_path text,status text not null default 'reported' check(status in ('reported','confirmed','investigating','resolved','resumed')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.work_stop_status_history(id bigint generated always as identity primary key,report_id uuid not null references public.work_stop_reports(id) on delete cascade,status text not null,note text,changed_by uuid not null references public.profiles(id),created_at timestamptz not null default now());
create table public.work_stop_protections(id uuid primary key default gen_random_uuid(),report_id uuid not null unique references public.work_stop_reports(id) on delete cascade,worker_id uuid not null references public.profiles(id),start_date timestamptz not null default now(),end_date timestamptz not null default now()+interval '30 days');
alter table public.work_stop_reports enable row level security; alter table public.work_stop_status_history enable row level security; alter table public.work_stop_protections enable row level security;
create policy "reports owner manager read" on public.work_stop_reports for select to authenticated using((select auth.uid())=reporter_id or (select private.is_manager()));
create policy "history owner manager read" on public.work_stop_status_history for select to authenticated using(exists(select 1 from public.work_stop_reports r where r.id=report_id and (r.reporter_id=(select auth.uid()) or (select private.is_manager()))));
create policy "protection owner manager read" on public.work_stop_protections for select to authenticated using((select auth.uid())=worker_id or (select private.is_manager()));
create or replace function public.create_work_stop_report(p_hazard_type text,p_description text,p_zone text,p_is_anonymous boolean,p_photo_path text default null) returns uuid language plpgsql security definer set search_path='' as $$ declare v_user uuid:=auth.uid();v_id uuid;begin if v_user is null then raise exception 'Authentication required';end if;insert into public.work_stop_reports(reporter_id,hazard_type,description,zone,is_anonymous,photo_path) values(v_user,p_hazard_type,p_description,p_zone,p_is_anonymous,p_photo_path) returning id into v_id;insert into public.work_stop_status_history(report_id,status,changed_by) values(v_id,'reported',v_user);insert into public.work_stop_protections(report_id,worker_id) values(v_id,v_user);return v_id;end;$$;
create or replace function public.transition_work_stop(p_id uuid,p_status text,p_note text default null) returns void language plpgsql security definer set search_path='' as $$ begin if not private.is_manager() then raise exception 'Manager required';end if;if p_status not in ('confirmed','investigating','resolved','resumed') then raise exception 'Invalid status';end if;update public.work_stop_reports set status=p_status,updated_at=now() where id=p_id;if not found then raise exception 'Report not found';end if;insert into public.work_stop_status_history(report_id,status,note,changed_by) values(p_id,p_status,p_note,auth.uid());end;$$;
revoke all on function public.create_work_stop_report(text,text,text,boolean,text),public.transition_work_stop(uuid,text,text) from public,anon; grant execute on function public.create_work_stop_report(text,text,text,boolean,text),public.transition_work_stop(uuid,text,text) to authenticated; grant select on public.work_stop_reports,public.work_stop_status_history,public.work_stop_protections to authenticated;
